    const verdict = await runReviewer({
      role: effectiveRole,
      model,
      modelRegistry: ctx.modelRegistry,
      thinkingLevel: ctx.thinkingLevel,
      cwd: config.obsidianRoot,
      signal,
      onProgress: (event) => {
        activity = event;
        options.onProgress?.(event);
      },
